selection-coding-delays.python_tests:
from delays import retry_delays
assert retry_delays(3,0,8)==[]
assert retry_delays(9,3,0)==[0,0,0]
assert retry_delays(0,3,7)==[0,0,0]
for args in [(-1,2,3),(1,-2,3),(1,2,-3)]:
    try:
        retry_delays(*args)
    except ValueError:
        pass
    else:
        raise AssertionError("negative accepted")

selection-coding-chunks.python_tests:
from chunks import split_chunks
x=[4,5]
assert split_chunks(x,5)==[[4,5]]
assert x==[4,5]
assert split_chunks([],2)==[]
assert split_chunks([1,2],1)==[[1],[2]]
for size in [0,-1]:
    try:
        split_chunks([1],size)
    except ValueError:
        pass
    else:
        raise AssertionError("bad size accepted")

selection-coding-pairs.python_tests:
from pairs import parse_pairs
assert parse_pairs("\n a : one \n a: two \n b: ")=={"a":"two","b":""}
assert parse_pairs("")=={}
for text in ["orphan",":bad","  : x"]:
    try:
        parse_pairs(text)
    except ValueError:
        pass
    else:
        raise AssertionError("invalid line accepted")
